package com.andye.warmod.radar.display.client;
import com.andye.warmod.radar.display.RadarDisplayConstants; import com.mojang.blaze3d.vertex.PoseStack; import com.mojang.blaze3d.vertex.VertexConsumer;
public final class RadarDisplayMapRenderer { private static final int BACKGROUND=0xFF04100D,OFFLINE_BACKGROUND=0xFF080B0C,FRAME=0xFF202B2F,GRID=0x442D7760,SWEEP=0xE85CF3A1,WARNING=0x99C58B35,FIRE=0x8872B7C4,CENTRE=0xFFFFC45A;private RadarDisplayMapRenderer(){} public static void renderTile(PoseStack.Pose pose,VertexConsumer buffer,RadarDisplayRenderState state){RadarDisplayPlaneTransform plane=new RadarDisplayPlaneTransform(state.facing);RadarDisplayPrimitiveBuilder.fill(pose,buffer,plane,-.002,-.002,1.002,1.002,0,state.online?BACKGROUND:OFFLINE_BACKGROUND);outer(pose,buffer,plane,state);if(!state.online){status(pose,buffer,plane,state);return;}RadarDisplayMapTransform map=new RadarDisplayMapTransform(state.radarCentre,state.width,state.height);grid(pose,buffer,plane,map,state);RadarDisplayMapTransform.Point centre=map.centre();RadarDisplayPrimitiveBuilder.globalRingForTile(pose,buffer,plane,centre.x(),centre.y(),map.worldRadiusToLocal(state.warningRadius),96,state.tileX,state.tileY,.012,.004,WARNING);RadarDisplayPrimitiveBuilder.globalRingForTile(pose,buffer,plane,centre.x(),centre.y(),map.worldRadiusToLocal(state.fireRadius),96,state.tileX,state.tileY,.012,.004,FIRE);double radius=RadarDisplayConstants.sweepRadius(state.width,state.height),angle=Math.toRadians(state.sweepAngleDegrees);RadarDisplayMapTransform.Point end=new RadarDisplayMapTransform.Point(centre.x()+Math.sin(angle)*radius,centre.y()+Math.cos(angle)*radius);RadarDisplayPrimitiveBuilder.globalRingForTile(pose,buffer,plane,centre.x(),centre.y(),radius,96,state.tileX,state.tileY,.006,.005,0x5545D98B);RadarDisplayPrimitiveBuilder.globalLineForTile(pose,buffer,plane,centre,end,state.tileX,state.tileY,.018,.007,SWEEP);for(var observation:state.observations){for(var route:observation.routes()){for(int i=0;i+1<route.points().size();i++){if(i>=route.completedSegments()&&(i&1)!=0)continue;RadarDisplayPrimitiveBuilder.globalLineForTile(pose,buffer,plane,map.map(route.points().get(i)),map.map(route.points().get(i+1)),state.tileX,state.tileY,i<route.completedSegments()?.019:.010,.005,observation.rgb());}}RadarDisplayPrimitiveBuilder.globalMarkerForTile(pose,buffer,plane,map.map(observation.observedPosition()),state.tileX,state.tileY,.025,.008,observation.rgb(),false);RadarDisplayPrimitiveBuilder.globalMarkerForTile(pose,buffer,plane,map.map(observation.predictedImpactPosition()),state.tileX,state.tileY,.025,.008,observation.rgb(),true);}RadarDisplayPrimitiveBuilder.globalMarkerForTile(pose,buffer,plane,centre,state.tileX,state.tileY,.025,.008,CENTRE,false);status(pose,buffer,plane,state);} private static void outer(PoseStack.Pose p,VertexConsumer b,RadarDisplayPlaneTransform plane,RadarDisplayRenderState s){double w=.024;if(s.tileX==0)RadarDisplayPrimitiveBuilder.line(p,b,plane,.01,0,.01,1,w,.01,FRAME);if(s.tileX==s.width-1)RadarDisplayPrimitiveBuilder.line(p,b,plane,.99,0,.99,1,w,.01,FRAME);if(s.tileY==0)RadarDisplayPrimitiveBuilder.line(p,b,plane,0,.01,1,.01,w,.01,FRAME);if(s.tileY==s.height-1)RadarDisplayPrimitiveBuilder.line(p,b,plane,0,.99,1,.99,w,.01,FRAME);} private static void grid(PoseStack.Pose p,VertexConsumer b,RadarDisplayPlaneTransform plane,RadarDisplayMapTransform m,RadarDisplayRenderState s){for(int x=0;x<=s.width;x++)RadarDisplayPrimitiveBuilder.globalLineForTile(p,b,plane,new RadarDisplayMapTransform.Point(x,0),new RadarDisplayMapTransform.Point(x,s.height),s.tileX,s.tileY,.006,.002,GRID);for(int y=0;y<=s.height;y++)RadarDisplayPrimitiveBuilder.globalLineForTile(p,b,plane,new RadarDisplayMapTransform.Point(0,y),new RadarDisplayMapTransform.Point(s.width,y),s.tileX,s.tileY,.006,.002,GRID);}private static void status(PoseStack.Pose p,VertexConsumer b,RadarDisplayPlaneTransform plane,RadarDisplayRenderState s){int colour=s.online?(s.stale?0xFFFFB84A:0xFF4FE7AA):(s.syncing?0xFFFFB84A:0xFFFF4747);RadarDisplayPrimitiveBuilder.fill(p,b,plane,.91,.91,.97,.97,.012,colour);} }